    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            if len(cells) == 9:
                rs = [y for y,x in cells]
                cs = [x for y,x in cells]
                if max(rs)-min(rs) == 2 and max(cs)-min(cs) == 2 and set(cells) == {(y,x) for y in range(min(rs),max(rs)+1) for x in range(min(cs),max(cs)+1)}:
                    objects.append((color, min(rs)+1, min(cs)+1))
    lines = {}
    for color, r, c in objects:
        for x in range(w):
            lines.setdefault((r,x), set()).add(color)
        for y in range(h):
            lines.setdefault((y,c), set()).add(color)
    for (r,c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
